owl:NamedIndividual.outputText:
/**设置显示模型中文名称项**/ PART_NAME=PTC_COMMON_NAME
/**设置显示模型重量**/ E_WGH=pro_mp_mass
/*将重量参数值由实数类型转化为字符串类型 if PRO_MP_MASS<0.1 重量 ="0.1" endif if PRO_MP_MASS>=1 重量 =extract(itos(PRO_MP_MASS*100),1,string_length(itos(PRO_MP_MASS*100))-2)+"."+extract(itos(PRO_MP_MASS*100),string_length(itos(PRO_MP_MASS*100))-1,2) endif if PRO_MP_MASS<1 & PRO_MP_MASS>=0.1 重量 =extract(itos(PRO_MP_MASS*100),1,string_length(itos(PRO_MP_MASS*100))-2)+"0."+extract(itos(PRO_MP_MASS*100),string_length(itos(PRO_MP_MASS*100))-1,2) endif
/*重量小于10时，3位小数 If PRO_MP_MASS<10 E_WGH=ceil(PRO_MP_MASS-0.0004,3) else endif
/*重量大于等于10且小于100时，2位小数 If PRO_MP_MASS>=10 & PRO_MP_MASS<100 E_WGH=ceil(PRO_MP_MASS-0.004,2) else endif /*重量大于等于100且小于1000时，1位小数 If PRO_MP_MASS>=100 & PRO_MP_MASS<1000 E_WGH=ceil(PRO_MP_MASS-0.04,1) else endif /*重量大于等于1000时，整数 If PRO_MP_MASS>=1000 E_WGH=ceil(PRO_MP_MASS-0.4) else endif

Bush_a=120 /*防雷螺柱间距角度
/*下端纵向定位判定 DI_BOTTOM_BUSH=DI_BOTTOM DI_TOP_BUSH=DI_TOP if TFL_BOTTOM > 100 bush_bottom_h = 50 else bush_bottom_h = TFL_BOTTOM/2 endif
/*上端纵向定位判定 if TFL_TOP > 100 bush_top_h = 50 else bush_top_h = TFL_TOP/2 endif
/*---------------------| 侧支撑 |------------------------------*/ $H1_S=-980*cos(Alpha)/*爬梯侧支撑距上法兰上端面安装高度
/*---------------------| 电缆线槽定位 |------------------------------*/ cable_up_circle =DA_TOP-2*S_TOP
/*---------------------| 休息踏板 |------------------------------*/ if $H_LADDER_TOP < 0 $rest1=-(280*10+140) else $rest1=-(280*11+140) endIF
/*---------------------| 过法兰支撑 |------------------------------*/ OFS_BOTTOM_H = 50 /*下方过法兰支撑距离底平面 DI_BOTTOM_OFS=DI_BOTTOM /*下方过法兰支撑所在位置内径 OFS_TOP_H = 50 /*上方过法兰支撑距离底平面 DI_TOP_OFS =DI_TOP /*上方过法兰支撑所在位置内径
